# 2. Custom CUDA kernel for transposed 1D convolution (naive dot product)
conv_transpose_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose_kernel(
    const float* __restrict__ input,
    const float* __restrict__ kernel,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int in_len
) {
    // Total number of elements to fill:
    const int total_elements = (batch_size * out_channels *
                               (in_len + 2*padding - kernel_size + 1) * stride +
                                (kernel_size - 1) * output_padding));
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Decode linear index to batch, out_channel and position along the length
        int pos = idx % ((in_len + 2*padding - kernel_size + 1) * stride +
                          (kernel_size - 1) * output_padding);
        int tmp = (idx / ((in_len + 2*padding - kernel_size + 1) * stride +
                           (kernel_size - 1) * output_padding)) % out_channels;

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            int input_start = batch_size * in_channels * in_len + ic * in_len;
            // Simple position offset: treat each thread as handling one element along the length
            int pos_offset = idx % in_len;
            for (int kk = 0; kk < kernel_size; ++kk) {
                int input_idx = input_start + pos_offset + kk;
                if (input_idx >= size(input)) break;
                float val_in = input[input_idx];
                // Kernel values are stored as [out_channels, in_channels, kernel_size]
                float val_k = kernel[tmp * in_channels + ic * kernel_size + kk];
                sum += val_in * val_k;
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv1d_transpose_cuda(torch::Tensor input, torch::Tensor kernel, bool bias) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv_transpose_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        kernel.data_ptr<float>(),
        out.data_ptr<float>(),
        torch::data_as_int(input.numel(), int)(0),   // batch size
        in_channels = kernel.size(1),                # in_channels from kernel shape
        out_channels,
        kernel.size(2),
        stride,
        padding,
        output_padding,
        groups = kernel.size(1),
        in_len = input.size(2)
    );

    return out;
}
"""

